from pathlib import Path
R=Path(__file__).resolve().parents[1];M=R/'srs/mockups'
css='''*{box-sizing:border-box}body{margin:0;color:#182a36;background:#f4f7f8;font:17px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button{cursor:pointer}button.primary{background:#086f68;border:0;color:white;padding:12px 20px;border-radius:9px;font-weight:650}.shell{display:flex;min-height:900px}.sidebar{width:216px;background:#152d3b;color:#b7c9d1;padding:34px 20px;display:flex;flex-direction:column;flex-shrink:0}.brand{font-size:29px;color:white;font-weight:750;letter-spacing:-1px;margin:0 12px 6px}.tag{font-size:12px;letter-spacing:1.4px;text-transform:uppercase;margin:0 12px 42px;color:#8ca8b5}.nav a{display:flex;align-items:center;gap:14px;padding:14px 12px;border-radius:9px;margin:6px 0;font-size:16px}.nav a.active{background:#28515c;color:white}.nav i{font-style:normal;font-size:12px;border:1px solid #6d8f9c;border-radius:5px;min-width:24px;text-align:center;padding:3px}.sidebottom{margin-top:auto;font-size:13px;padding:20px 12px 0;line-height:1.7}.main{padding:34px 40px;width:calc(100% - 216px)}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.eyebrow{color:#687f8d;font-size:12px;letter-spacing:1.8px;text-transform:uppercase;font-weight:700}h1{font-size:31px;letter-spacing:-.8px;margin:5px 0 2px}h2{font-size:20px;margin:0 0 18px;letter-spacing:-.3px}h3{font-size:18px;margin:0 0 12px}p{margin:7px 0}.muted{color:#6b7f8c;font-size:14px}.pill{font-size:13px;padding:5px 11px;border-radius:30px;background:#e7f4ef;color:#177258;font-weight:650}.pill.warn{background:#fff0d9;color:#976416}.pill.red{background:#fce9e6;color:#aa493b}.grid{display:grid;gap:20px}.stats{grid-template-columns:repeat(3,1fr);margin:22px 0}.card{background:#fff;border:1px solid #dde7ea;border-radius:13px;padding:23px}.stat small{color:#607784;font-size:14px}.number{font-size:31px;font-weight:700;letter-spacing:-1px;margin:9px 0 2px}.number span{font-size:15px;font-weight:500;color:#6c818c;letter-spacing:0}.stat.accent{background:#e8f3ef;border-color:#c9e3d9}.two{grid-template-columns:1.15fr 1fr}.flex{display:flex;align-items:center;justify-content:space-between;gap:15px}.positive{color:#0b7b65}.negative{color:#b35243}table{width:100%;border-collapse:collapse}th{text-align:left;font-weight:600;font-size:12px;color:#758994;padding:12px 10px;border-bottom:1px solid #dbe6ea;text-transform:uppercase;letter-spacing:.6px}td{font-size:15px;padding:16px 10px;border-bottom:1px solid #edf1f3}tr:last-child td{border:0}.right{text-align:right}.line{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #edf1f3}.line:last-child{border:0}.progress{height:9px;background:#edf2f3;border-radius:6px;overflow:hidden;margin-top:10px}.progress b{display:block;height:100%;border-radius:6px;background:#359c88}.progress b.orange{background:#df9b4b}.progress b.red{background:#c36152}.notice{border-left:3px solid #bd8240;background:#fff6e6;border-radius:7px;padding:14px 17px;font-size:14px;color:#775724;margin:18px 0}.note{padding:15px 0;font-size:14px;color:#607987}.filter{display:flex;gap:12px;margin:18px 0}input,select{border:1px solid #ccdce1;background:white;border-radius:7px;padding:11px 13px;color:#264250;width:100%;font-size:15px}label{display:block;font-size:13px;color:#526d7c;margin:16px 0 6px}.form h2{margin-bottom:5px}.tabs{display:flex;gap:7px;background:#edf3f4;padding:5px;border-radius:8px;margin:18px 0}.tabs span{flex:1;text-align:center;font-size:14px;padding:8px}.tabs .selected{background:white;border-radius:6px;color:#087267;font-weight:600;box-shadow:0 1px 4px #b4c3c633}.smallbutton{padding:7px 11px;border:1px solid #c8dcd9;border-radius:7px;background:white;color:#127569;font-size:13px}.formula{font-size:21px;font-weight:650;margin:16px 0;color:#155f58}.caption{font-size:12px;color:#82949c;margin-top:22px}.empty{text-align:center;padding:66px 20px}.empty .symbol{font-size:38px;color:#5c9289;margin-bottom:15px}.formError{color:#b34438;font-size:13px;margin:6px 0}.errorInput{border-color:#c86458;background:#fff8f6}.legend{display:flex;gap:18px;font-size:12px;color:#647d88}.legend span:before{content:"";width:8px;height:8px;display:inline-block;background:var(--dot,#258e7e);border-radius:8px;margin-right:6px}.formulaRows{font-size:14px}.compact td{padding:11px 8px}.footnote{font-size:12px;color:#6f8490;margin-top:15px}.badge{display:inline-block;background:#edf3f5;color:#577381;border-radius:5px;padding:3px 7px;font-size:12px}.nohistory{background:#f0f6f8;border:1px dashed #b4cdd5;padding:25px;border-radius:12px;margin:20px 0} @media(max-width:800px){.sidebar{width:160px;padding:20px 10px}.main{width:calc(100% - 160px);padding:22px}.stats,.two{grid-template-columns:1fr}.top{align-items:flex-start;gap:14px}.number{font-size:25px}}@media(max-width:560px){.shell{display:block}.sidebar{width:100%;padding:15px}.brand{font-size:23px}.tag,.sidebottom{display:none}.nav{display:flex;overflow-x:auto}.nav a{padding:8px;white-space:nowrap;font-size:12px}.nav i{display:none}.main{width:100%;padding:18px}.top{display:block}.top button{margin-top:14px}.filter{flex-wrap:wrap}.tablewrap{overflow:auto}.card{padding:18px}}'''
(M/'style.css').write_text(css)
nav=[('dashboard','Обзор'),('operations','Операции'),('budget','Бюджет'),('scheduled','Платежи'),('forecast','Прогноз')]
def page(file,title,content,active=None,button='Добавить операцию',sub='Демонстрационный бюджет · 26 октября 2026'):
 active=active or file
 topbutton=f'<a class="primaryLink" href="operations.html"><button class="primary">＋ {button}</button></a>' if button else ''
 html=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Баланс · {title}</title><link rel="stylesheet" href="style.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand">баланс<span style="color:#55bd9b">.</span></div><div class="tag">личные финансы</div><nav class="nav">'''+''.join(f'<a href="{f}.html" class="{"active" if f==active else ""}"><i>{i+1:02d}</i>{n}</a>' for i,(f,n) in enumerate(nav))+f'''</nav><div class="sidebottom">Единый бюджет · BYN<br><strong style="color:#f4fbfc">Учебный прототип</strong><br>Демонстрационные данные</div></aside><main class="main"><div class="top"><div><div class="eyebrow">Ваши деньги под контролем</div><h1>{title}</h1><p class="muted">{sub}</p></div>{topbutton}</div>{content}<div class="caption">БАЛАНС / МАКЕТ ИНТЕРФЕЙСА / SRS 0.2</div></main></div></body></html>'''
 (M/f'{file}.html').write_text(html)
def stat(label,val,note,accent=False):return f'<div class="card stat {"accent" if accent else ""}"><small>{label}</small><div class="number">{val} <span>BYN</span></div><div class="muted">{note}</div></div>'
def progress(name,amount,lim,color=''):
 return f'<div style="margin:23px 0"><div class="flex"><strong style="font-size:15px">{name}</strong><span style="font-size:14px">{amount} / {lim} BYN</span></div><div class="progress"><b class="{color}" style="width:{min(100,amount/lim*100)}%"></b></div></div>'
chart='''<svg viewBox="0 0 460 180" style="width:100%;margin:10px 0" aria-label="Доходы и расходы октября"><g stroke="#e9eff1"><path d="M40 25H440M40 65H440M40 105H440M40 145H440"/></g><g fill="#7b929d" font-size="11" font-family="Arial"><text x="0" y="29">1500</text><text x="5" y="69">1000</text><text x="10" y="109">500</text><text x="20" y="149">0</text><text x="45" y="173">1 окт</text><text x="170" y="173">10 окт</text><text x="300" y="173">20 окт</text><text x="405" y="173">26 окт</text></g><path d="M45 145 L100 25 L430 25" fill="none" stroke="#238f7b" stroke-width="3"/><path d="M45 135 L100 125 L165 106 L230 85 L295 78 L360 68 L430 65" fill="none" stroke="#db9e58" stroke-width="3"/></svg>'''
page('dashboard','Обзор бюджета','<div class="grid stats">'+stat('Текущий остаток','1 000,00','Все подтверждённые операции',True)+stat('Доходы октября','1 500,00','С 1 по 26 октября')+stat('Расходы октября','1 000,00','С 1 по 26 октября')+'</div><div class="grid two"><section class="card"><div class="flex"><h2>Движение денег</h2><span class="badge">Октябрь 2026</span></div>'+chart+'<div class="legend"><span>Доходы</span><span style="--dot:#db9e58">Расходы</span></div></section><section class="card"><div class="flex"><h2>Лимиты категорий</h2><a href="budget.html" class="muted">Все →</a></div>'+progress('Продукты',450,500)+progress('Транспорт',150,120,'red')+progress('Жильё и связь',400,450)+'<span class="pill red">Транспорт: превышение на 30 BYN</span></section></div><div class="grid two" style="margin-top:20px"><section class="card"><h2>Ожидается до конца месяца</h2><div class="line"><div><strong>Связь</strong><p class="muted">28 октября · регулярный платёж</p></div><strong>−100,00</strong></div><div class="note">Плановый платёж изменит остаток после подтверждения.</div></section><section class="card" style="background:#e8f3ef;border-color:#c9e3d9"><div class="flex"><h2>Остаток к концу месяца</h2><span class="pill">Оценка</span></div><div class="number">850,00 <span>BYN</span></div><p class="muted">Ещё 5 дней · средние расходы 10 BYN в день</p><p style="margin-top:17px"><a href="forecast.html" class="positive">Посмотреть расчёт →</a></p></section></div>')
rows='''<tr><td>26 окт</td><td><strong>Продукты</strong><p class="muted">Покупки на неделю</p></td><td class="right negative">−45,00</td></tr><tr><td>25 окт</td><td>Транспорт</td><td class="right negative">−12,00</td></tr><tr><td>22 окт</td><td>Продукты</td><td class="right negative">−28,50</td></tr><tr><td>20 окт</td><td>Жильё и связь<br><span class="badge">Связан с планом</span></td><td class="right negative">−100,00</td></tr><tr><td>5 окт</td><td>Зарплата</td><td class="right positive">+1 500,00</td></tr>'''
def operation_form(error=False):return '''<section class="card form"><h2>Новая операция</h2><p class="muted">Все суммы в белорусских рублях</p><div class="tabs"><span class="selected">Расход</span><span>Доход</span></div><form><label for="amount">Сумма, BYN</label><input id="amount" '''+('class="errorInput" value="−45" aria-invalid="true"' if error else 'value="45,00"')+'''><p class="formError">'''+('Введите сумму больше нуля, например 45,00.' if error else '')+'''</p><label for="date">Дата</label><input id="date" value="26.10.2026"><label for="category">Категория</label><select id="category"><option>Продукты</option><option>Транспорт</option><option>Жильё и связь</option></select><label for="comment">Комментарий</label><input id="comment" value="Покупки на неделю"><button type="button" class="primary" style="width:100%;margin-top:24px">Сохранить операцию</button><p class="footnote">Операция изменит фактический остаток после сохранения.</p></form></section>'''
operations='<div class="grid" style="grid-template-columns:1.35fr 1fr"><section class="card"><h2>История операций</h2><div class="filter"><select aria-label="Период"><option>Октябрь 2026</option></select><select aria-label="Тип"><option>Все типы</option></select></div><div class="tablewrap"><table><thead><tr><th>Дата</th><th>Категория</th><th class="right">Сумма, BYN</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="muted" style="margin-top:25px">Показаны 5 из 24 операций</p><div class="notice">Откройте запись, чтобы изменить её или удалить с подтверждением.</div></section>'
