page('input-error','Операции',operations+operation_form(True)+'</div>',active='operations',button=None)
page('budget','Категории и лимиты','<div class="flex" style="margin:20px 0"><span class="pill">Октябрь 2026</span><span class="muted">Фактические расходы за месяц</span></div><div class="grid two"><section class="card"><h2>Расходы по категориям</h2>'+progress('Продукты',450,500)+progress('Транспорт',150,120,'red')+progress('Жильё и связь',400,450)+'<div class="notice">Лимит транспорта превышен на 30,00 BYN. Новые расходы можно продолжать записывать.</div></section><section class="card form"><h2>Настройка лимита</h2><label for="month">Месяц</label><input id="month" value="Октябрь 2026"><label for="cat">Категория расходов</label><select id="cat"><option>Транспорт</option></select><label for="limit">Лимит, BYN</label><input id="limit" value="120,00"><button class="primary" style="margin-top:24px">Сохранить лимит</button><p class="note">Лимит относится к выбранному месяцу и категории.</p></section></div><section class="card" style="margin-top:20px"><div class="flex"><h2>Мои категории</h2><button class="smallbutton">＋ Создать категорию</button></div><table><thead><tr><th>Категория</th><th>Тип</th><th>Состояние</th><th>Действие</th></tr></thead><tbody><tr><td>Продукты</td><td>Расход</td><td><span class="pill">Активна</span></td><td>Изменить · Архивировать</td></tr><tr><td>Зарплата</td><td>Доход</td><td><span class="pill">Активна</span></td><td>Изменить · Архивировать</td></tr></tbody></table></section>',button=None)
page('scheduled','Плановые платежи','<div class="grid stats">'+stat('Доходы до конца октября','0,00','Ожидаемые поступления')+stat('Расходы до конца октября','100,00','1 неисполненный платёж',True)+stat('Расходы ноября','100,00','Для расчёта прогноза')+'</div><section class="card"><div class="flex"><h2>Расписание</h2><button class="smallbutton">＋ Регулярный платёж</button></div><table><thead><tr><th>Дата</th><th>Платёж</th><th>Сумма, BYN</th><th>Статус</th><th>Действие</th></tr></thead><tbody><tr><td>28 окт</td><td><strong>Связь</strong><p class="muted">Каждый месяц, 28 числа</p></td><td>−100,00</td><td><span class="pill warn">Ожидается</span></td><td><button class="smallbutton">Подтвердить</button></td></tr><tr><td>20 окт</td><td>Жильё и связь</td><td>−100,00</td><td><span class="pill">Исполнен</span></td><td>Открыть операцию →</td></tr><tr><td>5 окт</td><td>Зарплата</td><td>+1 500,00</td><td><span class="pill">Исполнен</span></td><td>Открыть операцию →</td></tr></tbody></table></section><div class="grid two" style="margin-top:20px"><section class="card"><h2>Как подтвердить платёж</h2><p>Создать фактическую операцию или связать платёж с уже введённой записью.</p><div class="note">Повторное подтверждение не создаёт второй расход.</div></section><section class="card"><h2>Если дата уже прошла</h2><p>Неисполненный платёж остаётся в прогнозе. Можно подтвердить оплату, пропустить или перенести его.</p><p class="muted" style="margin-top:15px">План сам по себе не меняет остаток денег.</p></section></div>',button=None)
page('forecast','Аналитика и прогноз','<div class="grid" style="grid-template-columns:1fr 1fr"><section class="card stat accent"><div class="flex"><small>Остаток на 31 октября</small><span class="pill">Оценка</span></div><div class="number">850,00 <span>BYN</span></div><p class="muted">После ожидаемых расходов до конца месяца</p></section><section class="card stat"><small>Расходы ноября</small><div class="number">400,00 <span>BYN</span></div><p class="muted">300,00 повседневные + 100,00 плановые</p></section></div><div class="grid two" style="margin-top:20px"><section class="card"><h2>Из чего складывается остаток</h2><div class="formulaRows"><div class="line"><span>Текущий фактический остаток</span><strong>1 000,00</strong></div><div class="line"><span>Ожидаемые доходы</span><strong>+0,00</strong></div><div class="line"><span>Плановые расходы</span><strong>−100,00</strong></div><div class="line"><span>5 дней × 10,00 BYN</span><strong>−50,00</strong></div></div><div class="formula">1 000 + 0 − 100 − 50 = 850 BYN</div><p class="muted">Текущий день считается завершённым. Убедитесь, что внесли все его операции.</p></section><section class="card"><h2>История для расчёта</h2><span class="pill">3 полных месяца</span><div class="line"><span>Период</span><strong>Июль–сентябрь</strong></div><div class="line"><span>Нерегулярные расходы</span><strong>920,00 BYN</strong></div><div class="line"><span>Календарные дни</span><strong>92</strong></div><div class="formula">920 / 92 = 10 BYN в день</div><p class="muted">Расходы, связанные с регулярными платежами, исключены из этой суммы.</p></section></div><section class="card" style="margin-top:20px"><div class="flex"><h2>Расходы октября по категориям</h2><span class="muted">Факт · 1 000,00 BYN</span></div><div class="grid" style="grid-template-columns:1fr 1fr 1fr"><div><strong>Продукты · 45%</strong><div class="progress"><b style="width:45%"></b></div></div><div><strong>Транспорт · 15%</strong><div class="progress"><b class="orange" style="width:15%"></b></div></div><div><strong>Жильё и связь · 40%</strong><div class="progress"><b style="width:40%"></b></div></div></div></section><p class="footnote">Оценка предполагает сохранение среднего уровня трат. Фактические расходы могут отличаться. Данные демонстрационные.</p>',button=None)
page('no-history','Аналитика и прогноз','<section class="card"><div class="nohistory"><span class="pill warn">Недостаточно истории</span><h2 style="margin-top:20px">Для прогноза нужен полный месяц учёта</h2><p>Учёт начат 15 октября 2026 года. Октябрь будет неполным месяцем и не войдёт в расчёт.</p><p class="muted" style="margin-top:14px">Первым полным месяцем может стать ноябрь. Прогноз станет доступен с 1 декабря, если вы будете записывать все операции.</p></div><h2>Что можно сделать сейчас</h2><p>Добавляйте доходы и расходы, устанавливайте лимиты и отмечайте регулярные платежи.</p><div style="margin-top:25px"><a href="operations.html"><button class="primary">Перейти к операциям</button></a></div></section><div class="grid stats">'+stat('Текущий остаток','1 000,00','Фактические данные доступны',True)+'<div class="card stat"><small>Остаток к концу месяца</small><div class="number">—</div><p class="muted">Нужен полный месяц истории</p></div><div class="card stat"><small>Расходы следующего месяца</small><div class="number">—</div><p class="muted">Нужен полный месяц истории</p></div></div>',active='forecast',button=None)
page('empty','Операции','<section class="card empty"><div class="symbol">＋</div><h2>Здесь появятся ваши операции</h2><p class="muted">Начните с первого дохода или расхода.<br>Начальный остаток не считается доходом.</p><div style="margin-top:26px"><a href="operations.html"><button class="primary">Добавить первую операцию</button></a></div></section>',active='operations',button=None)
